insert into public.questions (category_id, question, answers, correct_index, difficulty, tags, sort_order)
values
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie viele Stunden umfasst die betriebliche Projektarbeit für die Fachrichtung Anwendungsentwicklung maximal?', ARRAY['40 Stunden', '60 Stunden', '80 Stunden', '100 Stunden'], 2, 'easy', ARRAY['projektmanagement']::text[], 0),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Rolle spielt der Projektantrag laut den IHK-Hinweisen häufig im Kontakt mit dem Prüfungsausschuss?', ARRAY['Er ist ein rechtlich bindender Arbeitsvertrag.', 'Er dient als erste Visitenkarte für den Prüfling.', 'Er ist eine reine Formsache ohne Einfluss auf die Prüfer.', 'Er ist der unwichtigste Teil der gesamten Abschlussprüfung.'], 1, 'medium', ARRAY['arbeitsrecht', 'projektmanagement']::text[], 1),
  ((select id from public.question_categories where key = 'exam_prep'), 'Auf ungefähr wie vielen Seiten sollte eine Projektdokumentation in der Regel angemessen dargestellt werden?', ARRAY['5 Seiten', '10 Seiten', '15 Seiten', '30 Seiten'], 2, 'easy', ARRAY['projektmanagement']::text[], 2),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie sollte die veranschlagte Projektzeit bei der Dokumentation grob prozentual auf die Durchführung (inkl. Fehlersuche etc.) verteilt sein?', ARRAY['15 %', '25 %', '40 %', '60 %'], 3, 'medium', ARRAY['projektmanagement']::text[], 3),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lange sollten die Präsentation und das anschließende Fachgespräch idealerweise jeweils dauern?', ARRAY['Präsentation 20 Minuten, Fachgespräch 10 Minuten', 'Präsentation 15 Minuten, Fachgespräch 15 Minuten', 'Präsentation 10 Minuten, Fachgespräch 20 Minuten', 'Präsentation 30 Minuten, Fachgespräch 15 Minuten'], 1, 'medium', ARRAY['projektmanagement']::text[], 4),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie viel Zeit ist für die schriftliche Prüfung im Bereich ''Wirtschafts- und Sozialkunde'' vorgesehen?', ARRAY['45 Minuten', '60 Minuten', '90 Minuten', '120 Minuten'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 5),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie oft kann eine nicht bestandene IHK-Abschlussprüfung laut Verordnung wiederholt werden?', ARRAY['Einmal', 'Zweimal', 'Dreimal', 'Sie kann nicht wiederholt werden'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 6),
  ((select id from public.question_categories where key = 'exam_prep'), 'Bei welcher Punktzahl gilt eine Prüfungsleistung laut offiziellem IHK-Notenschlüssel noch als ''ausreichend''?', ARRAY['unter 30 - 0 Punkte', 'unter 50 - 30 Punkte', 'unter 67 - 50 Punkte', 'unter 81 - 67 Punkte'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 7),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie definiert die DSGVO den Begriff ''Profiling''?', ARRAY['Das Erstellen von Benutzerkonten in sozialen Netzwerken.', 'Jede Art der automatisierten Verarbeitung, um persönliche Aspekte wie Arbeitsleistung, wirtschaftliche Lage oder Interessen zu bewerten oder vorherzusagen.', 'Die manuelle Auswertung von Kundenfragebögen durch die Geschäftsleitung.', 'Das Sperren von IP-Adressen bei unbefugten Zugriffsversuchen.'], 1, 'medium', ARRAY['datenschutz', 'netzwerktechnik']::text[], 8),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter ''Pseudonymisierung'' gemäß Art. 4 DSGVO?', ARRAY['Das vollständige und unwiderrufliche Löschen eines Namens aus einer Datenbank.', 'Die Verarbeitung von Daten, sodass sie ohne Hinzuziehung zusätzlicher Informationen nicht mehr einer spezifischen Person zugeordnet werden können.', 'Die Nutzung eines Künstlernamens bei der Registrierung auf einer Website.', 'Die Veröffentlichung von Daten unter einer Creative-Commons-Lizenz.'], 1, 'medium', ARRAY['datenschutz', 'softwareentwicklung']::text[], 9),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer gilt als ''Verantwortlicher'' im Sinne des Datenschutzes?', ARRAY['Die natürliche oder juristische Person, die allein oder gemeinsam mit anderen über die Zwecke und Mittel der Verarbeitung entscheidet.', 'Der IT-Administrator, der die Server des Unternehmens wartet.', 'Der Datenschutzbeauftragte, der die Einhaltung der Gesetze kontrolliert.', 'Jede Person, die im Internet personenbezogene Daten liest.'], 0, 'medium', ARRAY['datenschutz']::text[], 10),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was definiert den Begriff ''Auftragsverarbeiter''?', ARRAY['Eine Person, die Daten für private Zwecke sammelt.', 'Eine Stelle, die personenbezogene Daten im Auftrag des Verantwortlichen verarbeitet.', 'Der Kunde, der seine Daten in ein Online-Formular einträgt.', 'Eine Behörde, die einen Untersuchungsauftrag gegen eine Firma leitet.'], 1, 'medium', ARRAY['datenschutz']::text[], 11),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Begriff beschreibt ''jeden mit oder ohne Hilfe automatisierter Verfahren ausgeführten Vorgang'' wie das Erheben, Speichern oder Löschen von Daten?', ARRAY['Übermittlung', 'Verarbeitung', 'Dokumentation', 'Archivierung'], 1, 'easy', ARRAY['datenschutz']::text[], 12),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Schutzziel stellt sicher, dass Systeme für berechtigte Nutzer funktionsfähig und die Daten jederzeit abrufbar sind?', ARRAY['Vertraulichkeit', 'Verfügbarkeit', 'Integrität', 'Authentizität'], 1, 'easy', ARRAY['it_sicherheit']::text[], 13),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter dem Begriff ''Authentisierung''?', ARRAY['Die Überprüfung der Richtigkeit von Datenpaketen.', 'Den Nachweis einer Identität, zum Beispiel durch einen Login mit Benutzername und Passwort.', 'Das Zuweisen von Ordnerberechtigungen für neue Mitarbeiter.', 'Das Verschlüsseln einer Festplatte.'], 1, 'easy', ARRAY['it_sicherheit']::text[], 14),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist ein ''ISMS'' laut der Norm ISO/IEC 27001?', ARRAY['Ein technisches System zur automatischen Datensicherung.', 'Ein Informationssicherheitsmanagementsystem zum Aufbau systematischer Sicherheitsprozesse.', 'Ein Programm zur Erkennung von Viren und Trojanern.', 'Ein Standard für die Programmierung sicherer Webseiten.'], 1, 'medium', ARRAY['it_sicherheit']::text[], 15),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Organisationsform ist dadurch gekennzeichnet, dass Mitarbeiter sowohl einer Fachabteilung als auch einer Projektleitung unterstellt sind?', ARRAY['Linien-Organisation', 'Matrix-Organisation', 'Autonome Projektorganisation', 'Hierarchische Struktur'], 1, 'medium', ARRAY['wirtschaft']::text[], 16),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Begriff beschreibt im Projektmanagement wesentliche Ereignisse oder Etappenziele, die den Fortschritt markieren?', ARRAY['Netzplan', 'Meilensteine', 'Sprints', 'Backlogs'], 1, 'easy', ARRAY['projektmanagement', 'scrum_agile']::text[], 17),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist laut DIN 69901 ein ''Projektmanagementsystem''?', ARRAY['Nur die Software (z.B. MS Project), die zur Planung genutzt wird.', 'Ein organisatorisch verankertes System mit Rollen, Verantwortlichkeiten und dokumentierten Methoden.', 'Die Summe aller im Unternehmen laufenden Projekte.', 'Ein Verfahren zur Auswahl der günstigsten Lieferanten.'], 1, 'hard', ARRAY['projektmanagement']::text[], 18),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was wird im QM-Kontext unter einem ''Audit'' verstanden?', ARRAY['Ein technischer Belastungstest für Software-Server.', 'Ein Untersuchungsverfahren zur Zertifizierung, bei dem die Einhaltung von Normen geprüft wird.', 'Das wöchentliche Team-Meeting zur Fehlerbesprechung.', 'Die automatische Korrektur von Programmierfehlern.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 19),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Prinzip steht im Zentrum des ''EFQM-Modells''?', ARRAY['Die maximale Einsparung von Personalkosten.', 'Der Einbezug aller Mitarbeiter in einen kontinuierlichen Verbesserungsprozess für hochwertige Produkte.', 'Die ausschließliche Kontrolle durch externe Prüfer.', 'Die Orientierung am günstigsten Preis auf dem Weltmarkt.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 20),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Begriff beschreibt im Qualitätsmanagement den ''prozessorientierten Ansatz''?', ARRAY['Dass jede Aufgabe unabhängig von anderen erledigt wird.', 'Dass Tätigkeiten als verknüpfte Prozesse verstanden, gesteuert und optimiert werden.', 'Dass nur das Endprodukt am Ende der Kette kontrolliert wird.', 'Dass die Führungsebene alle Entscheidungen allein trifft.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 21),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Reihenfolge stellt den korrekten zeitlichen Ablauf eines Projektes dar?', ARRAY['Projektplanung, Projektdurchführung, Projektabschluss, Projektauftrag/Projektdefinition', 'Projektauftrag/Projektdefinition, Projektplanung, Projektdurchführung, Projektabschluss', 'Projektdurchführung, Projektabschluss, Projektauftrag/Projektdefinition, Projektplanung', 'Projektauftrag/Projektdefinition, Projektdurchführung, Projektplanung, Projektabschluss'], 1, 'easy', ARRAY['projektmanagement']::text[], 22),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche der folgenden Aussagen zu Softwareentwicklungsmodellen ist korrekt?', ARRAY['Das Wasserfallmodell ist ein iteratives Modell.', 'Das Wasserfallmodell ist dokumentgetrieben.', 'Agile Modelle sind immer sequenzielle (lineare) Modelle.', 'Agile Vorgehensweisen verzichten vollständig auf Planung.'], 1, 'medium', ARRAY['scrum_agile', 'softwareentwicklung']::text[], 23),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür stehen die Abkürzungen im PDCA-Zyklus nach DIN EN ISO 9001?', ARRAY['Plan, Do, Check, Act', 'Product, Design, Code, Analyze', 'Plan, Define, Construct, Act', 'Process, Do, Check, Analyze'], 0, 'easy', ARRAY['projektmanagement', 'qualitaetsmanagement']::text[], 24),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche drei Faktoren bilden das sogenannte ''magische Dreieck'' des Projektmanagements, die sich gegenseitig beeinflussen?', ARRAY['Kosten, Zeit, Personal', 'Qualität, Risiko, Kommunikation', 'Kosten, Zeit, Qualität', 'Umfang, Ressourcen, Machbarkeit'], 2, 'easy', ARRAY['projektmanagement']::text[], 25),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Teamgröße wird für ein Scrum-Team empfohlen, da zu große Teams gegen die Scrum-Philosophie verstoßen würden?', ARRAY['1 bis 3 Personen', '3 bis 10 Personen', '15 bis 25 Personen', 'Mehr als 50 Personen'], 1, 'easy', ARRAY['scrum_agile']::text[], 26),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lange sollte ein sogenannter ''Sprint'' (Entwicklungszyklus) in Scrum üblicherweise dauern?', ARRAY['1 bis 4 Tage', '1 bis 4 Wochen', '1 bis 3 Monate', 'Mindestens ein halbes Jahr'], 1, 'easy', ARRAY['scrum_agile']::text[], 27),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer nimmt am ''Daily Scrum'' teil und wie lange dauert dieses Treffen in der Regel?', ARRAY['Nur der Scrum-Master und der Product-Owner für 30 Minuten.', 'Das gesamte Scrum-Team für maximal 15 Minuten.', 'Nur die Entwickler für 45 Minuten.', 'Das Scrum-Team und externe Stakeholder für eine Stunde.'], 1, 'medium', ARRAY['scrum_agile']::text[], 28),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie hoch ist die angestrebte und tolerierte Fehlerrate bei der Qualitätsmanagement-Methode Six Sigma (ausgedrückt in DPMO - defects per million opportunities)?', ARRAY['3,4 DPMO', '34 DPMO', '340 DPMO', '1000 DPMO'], 0, 'hard', ARRAY['qualitaetsmanagement']::text[], 29),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter testgetriebener Softwareentwicklung (Test-Driven Development, TDD)?', ARRAY['Tests werden erst ganz am Ende der Softwareentwicklung geschrieben.', 'Entwickler testen die Software nur manuell durch Durchklicken.', 'Tests werden vor dem eigentlichen Implementieren des Codes geschrieben und steuern die Entwicklung.', 'Ein separates Test-Team schreibt alle Tests unabhängig von den Entwicklern.'], 2, 'medium', ARRAY['softwareentwicklung']::text[], 30),
  ((select id from public.question_categories where key = 'exam_prep'), 'Worin besteht der wesentliche Unterschied zwischen Black-Box- und White-Box-Tests?', ARRAY['Black-Box-Tests prüfen die innere Logik, White-Box-Tests das Design.', 'Black-Box-Tests werden anhand der Spezifikation entwickelt (ohne Code-Kenntnis), White-Box-Tests prüfen den Quellcode und die innere Logik.', 'Black-Box-Tests sind manuelle Tests, White-Box-Tests sind immer automatisiert.', 'Es gibt keinen Unterschied, es sind nur zwei Begriffe für denselben Testansatz.'], 1, 'medium', ARRAY['softwareentwicklung']::text[], 31),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht die Abkürzung DSGVO, die maßgeblich den europäischen Datenschutz regelt?', ARRAY['Datenschutz-Gewährleistungsverordnung', 'Datenschutz-Grundverordnung', 'Deutsche Schutz- und Grundverordnung', 'Daten-Sicherheits- und Gewährleistungsordnung'], 1, 'easy', ARRAY['datenschutz']::text[], 32),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Recht gehört laut DSGVO ausdrücklich zu den Rechten betroffener Personen?', ARRAY['Recht auf Auskunft über die Daten Dritter', 'Recht auf unbegrenzte Datenspeicherung', 'Recht auf Löschung', 'Recht auf finanzielle Vergütung für Datennutzung'], 2, 'easy', ARRAY['datenschutz']::text[], 33),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Grundsatz zur Verarbeitung personenbezogener Daten ist in Artikel 5 der DSGVO gesetzlich verankert?', ARRAY['Datenmaximierung', 'Zweckbindung', 'Unbegrenzte Speicherung', 'Gewinnmaximierung durch Datenhandel'], 1, 'medium', ARRAY['datenschutz']::text[], 34),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was bedeutet ''Pseudonymisierung'' im Sinne der DSGVO?', ARRAY['Das vollständige Löschen von sensiblen Daten nach einer vorgegebenen Frist.', 'Die Verarbeitung von Daten, sodass diese ohne zusätzliche Informationen nicht mehr einer spezifischen Person zugeordnet werden können.', 'Das automatisierte Erstellen von Nutzerprofilen für Marketingzwecke.', 'Das öffentliche Teilen von Daten unter einem falschen Namen.'], 1, 'medium', ARRAY['datenschutz']::text[], 35),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche der folgenden Methoden ist ein typisches Szenario für Identitätsdiebstahl?', ARRAY['Ransomware', 'Adware', 'Phishing', 'Denial of Service (DoS)'], 2, 'easy', ARRAY['it_sicherheit']::text[], 36),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie unterscheiden sich die Konzepte Authentifizierung und Autorisierung voneinander?', ARRAY['Authentifizierung verschlüsselt Daten, Autorisierung entschlüsselt sie.', 'Authentifizierung vergibt Zugriffsrechte, Autorisierung verifiziert das Passwort.', 'Authentifizierung ist die Überprüfung der Echtheit (z. B. über ein Login), Autorisierung vergibt daraufhin spezielle Rechte.', 'Es gibt in der Praxis keinen Unterschied, beides ist derselbe Prozess.'], 2, 'medium', ARRAY['it_sicherheit']::text[], 37),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche drei Schutzziele werden bei der Analyse des Schutzbedarfes von IT-Systemen in der Regel bewertet?', ARRAY['Transparenz, Skalierbarkeit, Rentabilität', 'Vertraulichkeit, Integrität, Verfügbarkeit', 'Geschwindigkeit, Flexibilität, Design', 'Redundanz, Modularität, Komplexität'], 1, 'easy', ARRAY['it_sicherheit']::text[], 38),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was zeichnet das Bedrohungsszenario ''Ransomware'' aus?', ARRAY['Es verschlüsselt sensible Firmendaten oder sperrt Systeme, um anschließend Lösegeld zu erpressen.', 'Es überlastet Netzwerke durch massenhafte Anfragen, bis diese ausfallen.', 'Es liest unbemerkt Passwörter aus und sendet sie an den Angreifer.', 'Es platziert unerwünschte Werbeanzeigen im Browser des Nutzers.'], 0, 'medium', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 39),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist das primäre Ziel eines Penetrationstests?', ARRAY['Die physische Einbruchssicherheit des Serverraums zu testen.', 'Das Angriffspotenzial auf ein IT-Netz oder IT-System zu evaluieren, um vorhandene Schwachstellen aufzudecken.', 'Die korrekte Funktion von Antiviren-Software bei neuen Updates zu überprüfen.', 'Die Ladegeschwindigkeit von Webseiten unter extremen Bedingungen zu testen.'], 1, 'medium', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 40),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist ein wesentliches Merkmal der sogenannten ''Industrie 4.0''?', ARRAY['Die rein analoge und manuelle Fertigung ohne jeglichen Computereinsatz.', 'Der Einsatz von Dampfmaschinen zur massiven Produktionssteigerung.', 'Eine weitestgehend selbstorganisierte Produktion durch intelligente und digital vernetzte Systeme.', 'Die strikte physische Trennung von IT-Systemen und Produktionsmaschinen.'], 2, 'medium', ARRAY['netzwerktechnik']::text[], 41),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Protokoll wird häufig für die Datenübertragung im Internet der Dinge (IoT) eingesetzt, da es wenig Overhead und eine skalierbare Struktur bietet?', ARRAY['HTTP', 'FTP', 'MQTT', 'SMTP'], 2, 'medium', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 42),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Merkmal ist typisch für die Datenspeicherung in einer Blockchain?', ARRAY['Daten werden zentral auf einem einzigen Hauptserver verwaltet.', 'Jeder neue Block kann nachträglich beliebig verändert oder gelöscht werden.', 'Die Speicherung erfolgt dezentral (ohne zentrale Instanz) und Blöcke werden nach einem Konsensprinzip angefügt.', 'Eine Blockchain verzichtet aus Geschwindigkeitsgründen vollständig auf Verschlüsselung.'], 2, 'medium', ARRAY['it_sicherheit']::text[], 43),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was bewirkt eine Hashfunktion in der Informatik?', ARRAY['Sie komprimiert große Videodateien für den schnelleren E-Mail-Versand.', 'Sie wandelt eine Zeichenfolge von beliebiger Länge in eine Zeichenfolge fester Länge um.', 'Sie stellt gelöschte Daten auf fehlerhaften Festplatten wieder her.', 'Sie übersetzt den geschriebenen Quellcode in ausführbare Maschinensprache.'], 1, 'easy', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 44),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist das primäre Ziel beim Einsatz redundanter IT-Systeme (z. B. durch Server-Cluster oder Backup-Stromversorgung)?', ARRAY['Die Verringerung der Speicherkapazität zur maximalen Kostenersparnis.', 'Die Steigerung der grafischen Berechnungsgeschwindigkeit.', 'Die allgemeine Absicherung gegen Ausfälle zur Erhöhung der Ausfallsicherheit und Verfügbarkeit.', 'Die automatische Aktualisierung von Virenscannern.'], 2, 'easy', ARRAY['netzwerktechnik']::text[], 45),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was unterscheidet ein Hardware-RAID-System von einem Software-RAID-System?', ARRAY['Ein Hardware-RAID ist immer teurer, aber deutlich langsamer als ein Software-RAID.', 'Hardware-RAIDs funktionieren nur mit SSD-Laufwerken, Software-RAIDs nur mit alten HDDs.', 'Ein Hardware-RAID nutzt einen eigenen Controller zur Steuerung, während ein Software-RAID die Steuerung über die CPU des Hosts regelt.', 'Es gibt keinen technischen Unterschied, es sind lediglich zwei Marketingbegriffe.'], 2, 'hard', ARRAY['netzwerktechnik']::text[], 46),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist ein wesentlicher Unterschied zwischen einem SAN (Storage Area Network) und einem NAS (Network Attached Storage)?', ARRAY['Ein NAS stellt Daten auf Dateiebene (wie ein Dateiserver) bereit, ein SAN stellt in der Regel Speicher auf Blockebene zur Verfügung.', 'Ein NAS stellt Speicher auf Blockebene bereit, ein SAN ausschließlich auf Dateiebene.', 'Ein SAN ist nur für Heimanwender gedacht, NAS-Systeme dürfen nur in Großkonzernen genutzt werden.', 'Ein NAS kann im Gegensatz zum SAN nicht an ein normales Ethernet-Netzwerk angeschlossen werden.'], 0, 'hard', ARRAY['netzwerktechnik', 'wirtschaft']::text[], 47),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher USV-Typ (Unterbrechungsfreie Stromversorgung) schützt sensible Systeme am besten, da es hier keine Umschaltzeiten gibt und die Ausgangsspannung komplett von der USV erzeugt wird?', ARRAY['Offline-USV', 'Netzinteraktive USV (VI)', 'Online-USV (VFD)', 'Online-USV (VFI)'], 3, 'hard', ARRAY['netzwerktechnik']::text[], 48),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht die Abkürzung ''API'' im Bereich der Anwendungsentwicklung?', ARRAY['Advanced Programming Integration', 'Automated Process Instruction', 'Application Programming Interface', 'Application Process Internet'], 2, 'easy', ARRAY['softwareentwicklung']::text[], 49),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist ein typisches Beispiel für eine ''nicht-funktionale Anforderung'' an eine neue Software?', ARRAY['Die Software muss Kundendaten in einer Tabelle anzeigen und sortieren können.', 'Die Anwendung soll effizient arbeiten, z.B. mit einer schnellen Reaktionszeit und geringem Ressourcenverbrauch.', 'Das System muss eine Export-Funktion für PDF-Dateien besitzen.', 'Ein Administrator muss über eine Oberfläche Passwörter der Nutzer zurücksetzen können.'], 1, 'medium', ARRAY['softwareentwicklung']::text[], 50),
  ((select id from public.question_categories where key = 'exam_prep'), 'Worin besteht ein zentraler Unterschied zwischen einer relationalen Datenbank und einer klassischen NoSQL-Datenbank?', ARRAY['Relationale Datenbanken speichern nur Texte, NoSQL-Datenbanken nur Multimedia-Dateien.', 'Relationale Datenbanken sind komplett veraltet und werden in der Praxis nicht mehr genutzt.', 'NoSQL-Datenbanken nutzen standardmäßig immer komplexe SQL-Joins über Dutzende Tabellen.', 'Relationale Datenbanken basieren auf Tabellen und festen Beziehungen, NoSQL-Datenbanken (z.B. dokumentenorientiert) kommen in der Regel ohne starres SQL-Tabellenschema aus.'], 3, 'medium', ARRAY['softwareentwicklung']::text[], 51),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was unterscheidet die Versionsverwaltung ''Git'' grundlegend von ''Subversion'' (SVN)?', ARRAY['Git ist ein verteiltes System, bei dem jeder Nutzer eine lokale Kopie des gesamten Repositories besitzt; SVN ist ein zentral verwaltetes System.', 'Git hat ausschließlich ein zentrales Repository auf einem Server, SVN arbeitet rein lokal.', 'Git kann nur den Code von Web-Anwendungen verwalten, SVN ist für Desktop-Software gedacht.', 'Git benötigt permanent eine aktive Internetverbindung, um Code schreiben zu können, SVN hingegen nicht.'], 0, 'medium', ARRAY['softwareentwicklung']::text[], 52),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Merkmal beschreibt die ''Deklarative Programmierung'' am besten?', ARRAY['Das Programm gibt dem Computer ganz genaue Schritt-für-Schritt-Befehle vor (wie ''Was ist zu tun'').', 'Die Realität wird detailgetreu durch das Zusammenspiel von Klassen und Objekten modelliert.', 'Der Fokus liegt auf der Beschreibung des Problems (das ''Was''), die Umsetzung erfolgt dann oft automatisch (z.B. bei SQL).', 'Es wird gänzlich auf Variablen verzichtet und nur mit hardwarenahem Maschinencode gearbeitet.'], 2, 'medium', ARRAY['softwareentwicklung']::text[], 53),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher der folgenden SQL-Befehle gehört in die Kategorie der DDL (Data Definition Language)?', ARRAY['SELECT', 'UPDATE', 'CREATE', 'INSERT'], 2, 'easy', ARRAY['softwareentwicklung']::text[], 54),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Entwurfsmuster (Design Pattern) dient dazu, sicherzustellen, dass von einer bestimmten Klasse genau ein einziges Objekt instanziiert wird, das global zur Verfügung steht?', ARRAY['Observer-Muster', 'Model-View-Controller (MVC)', 'Singleton-Muster', 'Factory-Muster'], 2, 'medium', ARRAY['netzwerktechnik', 'softwareentwicklung']::text[], 55),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht die Abkürzung DMZ im Bereich der Netzwerksicherheit?', ARRAY['Direct Managed Zone', 'Demilitarized Zone', 'Domain Manipulation Zone', 'Decentralized Management Zone'], 1, 'easy', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 56),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Verschlüsselungsart nutzt das SSL/TLS-Protokoll in der Regel für die sichere Datenübertragung bei webbasierten Anwendungen?', ARRAY['Ausschließlich symmetrische Verschlüsselung', 'Ausschließlich asymmetrische Verschlüsselung', 'Eine Kombination aus symmetrischer und asymmetrischer Verschlüsselung', 'Überhaupt keine Verschlüsselung, es nutzt nur Hashwerte'], 2, 'medium', ARRAY['it_sicherheit']::text[], 57),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Protokoll wird bei Voice over IP (VoIP) typischerweise für den eigentlichen Echtzeit-Transport der Audio-Datenpakete eingesetzt?', ARRAY['HTTP (Hypertext Transfer Protocol)', 'FTP (File Transfer Protocol)', 'RTP (Real Time Transport Protocol) basierend auf UDP', 'SMTP (Simple Mail Transfer Protocol)'], 2, 'medium', ARRAY['netzwerktechnik']::text[], 58),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchen wesentlichen Zweck hat der Einsatz eines sogenannten ''VLAN-Tags'' in einem Netzwerk?', ARRAY['Es weist dem Computer dynamisch eine IP-Adresse zu.', 'Es ordnet Datenpakete auf Trunk-Leitungen eindeutig einem bestimmten virtuellen Netzwerk (VLAN) zu.', 'Es verschlüsselt die Datenpakete auf Hardware-Ebene.', 'Es blockiert Viren und Malware am Switch-Port.'], 1, 'medium', ARRAY['netzwerktechnik']::text[], 59),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür wird das SAML-Protokoll (Security Assertion Markup Language) im Web-Umfeld häufig verwendet?', ARRAY['Für die Implementierung von Single Sign-On (SSO) und den Austausch von Authentifizierungsdaten.', 'Für das dynamische Routing zwischen mehreren Server-Standorten.', 'Für den Aufbau eines verschlüsselten IPsec-VPN-Tunnels.', 'Zur automatischen Fehlerkorrektur bei mangelhaften WLAN-Verbindungen.'], 0, 'hard', ARRAY['it_sicherheit', 'netzwerktechnik']::text[], 60),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchem Support-Level werden in der Regel die höchsten Eskalationsstufen, die komplexesten Probleme und der Kontakt zu IT-Spezialisten der Hersteller gebündelt?', ARRAY['First-Level-Support', 'Second-Level-Support', 'Third-Level-Support', 'Fourth-Level-Support'], 2, 'easy', ARRAY['wirtschaft']::text[], 61),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Vertragsart liegt bei der Bereitstellung von ''Software as a Service'' (SaaS) über das Internet rechtlich in den meisten Fällen zugrunde?', ARRAY['Kaufvertrag', 'Werkvertrag', 'Mietvertrag', 'Dienstvertrag'], 2, 'medium', ARRAY['softwareentwicklung', 'wirtschaft']::text[], 62),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie hoch ist das gesetzlich vorgeschriebene Mindestkapital (Stammkapital) bei der Gründung einer GmbH (Gesellschaft mit beschränkter Haftung)?', ARRAY['10.000 Euro', '25.000 Euro', '50.000 Euro', 'Ein Mindestkapital ist gesetzlich nicht erforderlich.'], 1, 'medium', ARRAY['arbeitsrecht', 'wirtschaft']::text[], 63),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie viele Werktage Erholungsurlaub stehen einem/einer Auszubildenden unter 17 laut Jugendarbeitsschutzgesetz mindestens zu, wenn er/sie zu Beginn des Kalenderjahres noch nicht 17 Jahre alt ist?', ARRAY['Mindestens 24 Werktage', 'Mindestens 25 Werktage', 'Mindestens 27 Werktage', 'Mindestens 30 Werktage'], 2, 'medium', ARRAY['arbeitsrecht', 'wirtschaft']::text[], 64),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche drei Dimensionen der Nachhaltigkeit sollten bei der Unternehmensausrichtung gleichwertig berücksichtigt werden, da sie sich gegenseitig beeinflussen?', ARRAY['Produktion, Marketing, Vertrieb', 'Ökonomie, Ökologie, Soziales', 'Hardware, Software, Netzwerke', 'Einkauf, Lagerhaltung, Transport'], 1, 'easy', ARRAY['datenanalyse', 'netzwerktechnik']::text[], 65),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was kennzeichnet die sogenannte ''Induktive Datenanalyse''?', ARRAY['Sie versucht, Daten lediglich in eine übersichtliche Form wie Tabellen oder Grafiken zu bringen.', 'Sie sammelt unstrukturiert Daten, um erst im Nachhinein mögliche Fragestellungen zu entwickeln.', 'Sie versucht, aufgrund von erhobenen Daten oder Stichproben auf Gesamtheiten zu schließen (z. B. mithilfe der Wahrscheinlichkeitstheorie).', 'Sie befasst sich ausschließlich mit der Archivierung von Rohdaten in einem Data Warehouse.'], 2, 'medium', ARRAY['datenanalyse']::text[], 66),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht das Phasenmodell ''CRISP-DM'', das als Methodik bei Data-Mining-Projekten eingesetzt wird?', ARRAY['Critical Response Integration System Process for Data Mining', 'Cross Industry Standard Process for Data Mining', 'Complex Research Interface for Statistical Process Data Models', 'Creative Routine for Intelligent Software Programming Data Mining'], 1, 'medium', ARRAY['datenanalyse']::text[], 67),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was beschreibt der Begriff ''Entropie'' im Kontext der Informationstheorie und Datenanalyse?', ARRAY['Die physische Speicherkapazität einer Datenbank in Terabyte.', 'Die maximale Übertragungsgeschwindigkeit eines Netzwerks bei Volllast.', 'Ein Verschlüsselungsalgorithmus für sichere Passwörter.', 'Ein Maß für den mittleren Informationsgehalt einer Nachrichtenquelle.'], 3, 'hard', ARRAY['datenanalyse', 'it_sicherheit', 'netzwerktechnik', 'softwareentwicklung']::text[], 68),
  ((select id from public.question_categories where key = 'exam_prep'), 'Worin besteht der wesentliche Unterschied zwischen ''Clustering'' und ''Klassifikation'' beim maschinellen Lernen?', ARRAY['Clustering teilt Daten anhand von Ähnlichkeiten in neue Gruppen (Cluster) ein, während die Klassifikation neue Daten in bereits vordefinierte (bekannte) Klassen einordnet.', 'Clustering wird ausschließlich für Bilddateien genutzt, Klassifikation nur für reine Textdaten.', 'Klassifikation sucht nach Gemeinsamkeiten ohne jegliche Zielvorgabe, Clustering nutzt vorab trainierte Klassen.', 'Es gibt keinen technischen Unterschied, es handelt sich lediglich um synonyme Begriffe.'], 0, 'medium', ARRAY['datenanalyse', 'qualitaetsmanagement']::text[], 69),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Aussage beschreibt das Pareto-Prinzip (im Kontext der Prozessanalyse) am zutreffendsten?', ARRAY['50 % des Aufwands führen in Geschäftsprozessen immer zu exakt 50 % des Ertrags.', 'Mit 20 % Einsatz (Aufwand) kann oft bereits ein Ertrag (Wirkung) von 80 % erreicht werden.', 'Ein Prozess darf maximal 20 Fehler pro einer Million Durchläufe aufweisen, um rentabel zu sein.', 'Eine 100%ige Qualität ist nur durch eine 100%ige manuelle Prüfung aller Einzelschritte erreichbar.'], 1, 'easy', ARRAY['qualitaetsmanagement', 'wirtschaft']::text[], 70),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist der Hauptzweck eines Ishikawa-Diagramms (auch Fischgrätendiagramm genannt)?', ARRAY['Die Visualisierung von objektorientiertem Code.', 'Die rein zeitliche Projektplanung mit Meilensteinen und Pufferzeiten.', 'Die Identifikation und Strukturierung von Ursachen und deren Wirkung auf ein bestimmtes Problem zur Fehleranalyse.', 'Die Berechnung von Hardwarekosten für neue IT-Systeme.'], 2, 'medium', ARRAY['projektmanagement', 'qualitaetsmanagement', 'softwareentwicklung']::text[], 71),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht die Abkürzung FMEA in der Qualitäts- und Fehleranalyse?', ARRAY['Fast Method for Evaluation and Analysis', 'File Management and Extraction Algorithm', 'Fault Matrix for Enterprise Applications', 'Failure Mode and Effects Analysis (Fehlermöglichkeits- und -einflussanalyse)'], 3, 'medium', ARRAY['qualitaetsmanagement']::text[], 72),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird die sogenannte Risiko-Prioritätszahl (RPZ) im Rahmen einer FMEA zur Bewertung von Fehlern berechnet?', ARRAY['Auftretenswahrscheinlichkeit + Bedeutung + Entdeckungswahrscheinlichkeit', 'Bedeutung * Entdeckungswahrscheinlichkeit', 'Auftretenswahrscheinlichkeit * Bedeutung * Entdeckungswahrscheinlichkeit', 'Auftretenswahrscheinlichkeit / Entdeckungswahrscheinlichkeit'], 2, 'hard', ARRAY['qualitaetsmanagement']::text[], 73),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher wesentliche Unterschied besteht beim V-Modell im Vergleich zum klassischen Wasserfallmodell?', ARRAY['Es verzichtet vollständig auf Testphasen.', 'Es ordnet jeder Entwicklungsphase direkt eine entsprechende Testphase (z. B. Integrationstest zur System-Architektur) gegenüber.', 'Es ist ein rein agiles Modell ohne Dokumentation.', 'Es wurde ausschließlich für die Hardwareentwicklung konzipiert.'], 1, 'medium', ARRAY['scrum_agile']::text[], 74),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche der folgenden Rollen gehört laut Scrum NICHT zum eigentlichen Scrum-Team, sondern vertritt externe Interessen?', ARRAY['Der Scrum Master', 'Der Product Owner', 'Die Entwickler (Teil des Scrum-Teams)', 'Die Stakeholder'], 3, 'easy', ARRAY['scrum_agile']::text[], 75),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchem Zweck dient das Observer-Entwurfsmuster (Beobachter-Muster) in der objektorientierten Softwareentwicklung?', ARRAY['Es stellt sicher, dass eine Klasse nur genau ein Objekt instanziiert.', 'Es trennt die Benutzeroberfläche von der Datenbank.', 'Es definiert eine Abhängigkeit, sodass bei der Zustandsänderung eines Subjekts automatisch alle registrierten Beobachter benachrichtigt und aktualisiert werden.', 'Es übersetzt den Quellcode in ausführbare Maschinensprache.'], 2, 'medium', ARRAY['softwareentwicklung']::text[], 76),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Nutzungsmodell im Cloud-Computing stellt Anwendern eine komplette, lauffähige Softwareanwendung über das Internet zur Verfügung (Software on demand)?', ARRAY['Infrastructure as a Service (IaaS)', 'Platform as a Service (PaaS)', 'Software as a Service (SaaS)', 'Network as a Service (NaaS)'], 2, 'easy', ARRAY['softwareentwicklung']::text[], 77),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Beziehung in einem UML-Use-Case-Diagramm wird verwendet, um auszudrücken, dass ein Anwendungsfall unter bestimmten Bedingungen (optional) durch einen anderen erweitert wird?', ARRAY['<<include>>', '<<extend>>', 'Vererbung', 'Generalisierung'], 1, 'medium', ARRAY['softwareentwicklung']::text[], 78),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird eine n:m-Beziehung zwischen zwei Entitäten in einem relationalen Datenbankmodell in der Regel physisch umgesetzt?', ARRAY['Die Tabelle der n-Seite erhält einen Fremdschlüssel.', 'Die Tabelle der 1-Seite erhält einen Fremdschlüssel.', 'Die beiden Tabellen verschmelzen immer zu einer einzigen großen Tabelle.', 'Es wird eine zusätzliche Tabelle erzeugt, welche die Primärschlüssel der beiden anderen Tabellen als Fremdschlüssel aufnimmt.'], 3, 'medium', ARRAY['softwareentwicklung']::text[], 79),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches der folgenden Verfahren ist ein konkretes Beispiel für eine asymmetrische Verschlüsselung (die Nutzung von einem Public und einem Private Key)?', ARRAY['AES (Advanced Encryption Standard)', 'DES (Data Encryption Standard)', 'RSA (Rivest-Shamir-Adleman)', 'MD5-Hashfunktion'], 2, 'medium', ARRAY['it_sicherheit']::text[], 80),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Netzwerktopologie liegt vor, wenn alle Endgeräte (z. B. PCs) einzeln an einen zentralen Knotenpunkt (wie einen Switch) angeschlossen sind?', ARRAY['Ringtopologie', 'Bustopologie', 'Sterntopologie', 'Vermaschte Topologie'], 2, 'easy', ARRAY['netzwerktechnik']::text[], 81),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Protokoll wird bei Voice over IP (VoIP) eingesetzt, um die digitalisierten Sprachdatenpakete verbindungslos (auf Basis von UDP) über das Netzwerk zu transportieren?', ARRAY['HTTP', 'FTP', 'RTP (Real Time Transport Protocol)', 'SMTP'], 2, 'easy', ARRAY['netzwerktechnik']::text[], 82),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist das ''Product Backlog'' als Scrum-Artefakt?', ARRAY['Eine lauffähige Software am Ende des Projekts.', 'Das Budget, das für die Entwicklung der Software zur Verfügung steht.', 'Eine Liste aller Anforderungen für das zu entwickelnde Produkt.', 'Ein Fehlerbericht, der vom Scrum Master an die Stakeholder übergeben wird.'], 2, 'easy', ARRAY['scrum_agile']::text[], 83),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird das ''Sprint Backlog'' in Scrum definiert?', ARRAY['Es ist die Gesamtheit aller Anforderungen des gesamten Projekts.', 'Es ist eine Liste aller Anforderungen aus dem Product Backlog, die im nächsten Sprint umgesetzt werden sollen.', 'Es ist das fertige und fehlerfreie Produkt am Ende der Entwicklung.', 'Es ist das tägliche Besprechungsprotokoll des Entwicklerteams.'], 1, 'easy', ARRAY['scrum_agile']::text[], 84),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter dem ''Produktinkrement'' als Scrum-Artefakt?', ARRAY['Eine detaillierte Zeitplanung (Gantt-Diagramm) für die kommenden vier Wochen.', 'Die Liste der Anforderungen für den allerersten Sprint.', 'Eine lauffähige Software, die am Ende eines Sprints alle geplanten Anforderungen aus dem Product Backlog umgesetzt hat.', 'Die vertragliche Vereinbarung (SLA) zwischen dem Kunden und dem Scrum Team.'], 2, 'medium', ARRAY['projektmanagement', 'scrum_agile']::text[], 85),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was besagt der in Artikel 5 der DSGVO verankerte Grundsatz der ''Datenminimierung''?', ARRAY['Personenbezogene Daten müssen nach genau 30 Tagen unwiderruflich gelöscht werden.', 'Unternehmen dürfen ausschließlich pseudonymisierte Daten verarbeiten.', 'Personenbezogene Daten müssen dem Zweck angemessen, erheblich und auf das für die Verarbeitung notwendige Maß beschränkt sein.', 'Die Speicherkapazität der Unternehmensserver muss zur Kostensenkung so klein wie möglich gehalten werden.'], 2, 'medium', ARRAY['datenschutz']::text[], 86),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Entwicklungsleiter befürchtet, dass die geplante Speicherung von Kundendaten in direkter Verbindung mit Projekten gegen die Datenminimierung verstößt. Wie ist diese Situation zu beurteilen?', ARRAY['Das Vorgehen ist zulässig, solange nur die Daten gespeichert werden, die zwingend erforderlich sind, um die Aufgabe (z. B. eine sinnvolle Kundenbetreuung) zu erfüllen.', 'Die Befürchtung ist berechtigt, da das Prinzip die dauerhafte Speicherung von Kundendaten strikt verbietet.', 'Die Befürchtung ist falsch, da das Prinzip der Datenminimierung ausschließlich für Mitarbeiterdaten des eigenen Unternehmens gilt.', 'Das Vorgehen ist rechtlich problematisch, da Kundendaten und Projektdaten nach der DSGVO immer auf physisch komplett getrennten Servern liegen müssen.'], 0, 'hard', ARRAY['datenschutz']::text[], 87),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Haftung gilt für den Inhaber eines Einzelunternehmens gegenüber Außenstehenden?', ARRAY['Beschränkt auf das Geschäftsvermögen.', 'Nur bis zu einer Höhe von 25.000 €.', 'Persönlich und unbeschränkt.', 'Solidarisch mit den Angestellten.'], 2, 'easy', ARRAY['wirtschaft']::text[], 88),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie erfolgt die Gewinnverteilung bei einer GbR (Gesellschaft bürgerlichen Rechts), sofern vertraglich nichts anderes bestimmt wurde?', ARRAY['Im Verhältnis der Kapitaleinlage.', 'Nach Köpfen gemäß § 722 BGB.', 'Alleinige Zuweisung an den Geschäftsführer.', '4 % auf die Einlage, der Rest nach Köpfen.'], 1, 'medium', ARRAY['wirtschaft']::text[], 89),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Merkmal ist ein typischer Nachteil einer OHG (Offenen Handelsgesellschaft)?', ARRAY['Hohes Risiko durch die unbeschränkte Privathaftung aller Gesellschafter.', 'Ein Mindestkapital von 50.000 € ist erforderlich.', 'Die Gründungskosten betragen ca. 1.500 €.', 'Es ist nur eine Person als Gründer möglich.'], 0, 'medium', ARRAY['wirtschaft']::text[], 90),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer ist in einer Kommanditgesellschaft (KG) zur Geschäftsführung berechtigt?', ARRAY['Alle Gesellschafter (Komplementäre und Kommanditisten).', 'Nur die Kommanditisten.', 'Nur die Komplementäre (Vollhafter).', 'Ein externer, notariell bestellter Vorstand.'], 2, 'medium', ARRAY['wirtschaft']::text[], 91),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie hoch muss das gezeichnete Kapital (Grundkapital) bei der Gründung einer Aktiengesellschaft (AG) mindestens sein?', ARRAY['25.000,00 €', 'Es gibt keine Untergrenze.', '50.000,00 €', '100.000,00 €'], 2, 'medium', ARRAY['wirtschaft']::text[], 92),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Vorteil ergibt sich bei der Wahl einer GmbH gegenüber einer OHG?', ARRAY['Geringere Gründungskosten von ca. 30 €.', 'Die Haftung ist auf das Gesellschaftsvermögen beschränkt.', 'Es ist keine Eintragung in das Handelsregister nötig.', 'Die Gewinnverteilung erfolgt immer nach Köpfen.'], 1, 'easy', ARRAY['wirtschaft']::text[], 93),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Organe sind bei einer Aktiengesellschaft (AG) zwingend vorgeschrieben?', ARRAY['Nur der Geschäftsführer.', 'Hauptversammlung, Aufsichtsrat und Vorstand.', 'Komplementär und Kommanditist.', 'Einziger Gesellschafter und Prokurist.'], 1, 'medium', ARRAY['wirtschaft']::text[], 94),
  ((select id from public.question_categories where key = 'exam_prep'), 'Auf welcher gesetzlichen Grundlage basiert die Kommanditgesellschaft (KG)?', ARRAY['GmbH-Gesetz', 'Aktiengesetz', '§ 161 ff. HGB', '§ 705 ff. BGB'], 2, 'hard', ARRAY['wirtschaft']::text[], 95),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Namenszusatz ist für ein Einzelunternehmen zwingend erforderlich, wenn es im Handelsregister eingetragen ist?', ARRAY['GbR', 'GmbH', 'e. K., e. Kffr. oder e. Kfm.', 'OHG'], 2, 'medium', ARRAY['wirtschaft']::text[], 96),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie viel des Stammkapitals muss bei einer GmbH-Gründung sofort eingezahlt werden?', ARRAY['100 %', '50 %', '25 %', 'Es ist keine Soforteinzahlung nötig.'], 1, 'medium', ARRAY['wirtschaft']::text[], 97),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wann müssen die wesentlichen Inhalte des Berufsausbildungsvertrages spätestens niedergeschrieben und von den Beteiligten unterzeichnet werden?', ARRAY['Innerhalb des ersten Monats der Ausbildung.', 'Vor Beginn der Ausbildung.', 'Unmittelbar nach der Eintragung bei der IHK.', 'Erst nach bestandener Probezeit.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 98),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche gesetzliche Unter- und Obergrenze gilt für die Probezeit in einem Berufsausbildungsverhältnis?', ARRAY['Mindestens 1 Monat, höchstens 3 Monate.', 'Mindestens 1 Monat, höchstens 4 Monate.', 'Mindestens 3 Monate, höchstens 6 Monate.', 'Es gibt keine gesetzliche Untergrenze, nur eine Obergrenze von 4 Monaten.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 99),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer hat dem Auszubildenden die für die Ausbildung und die Zwischen- und Abschlussprüfungen erforderlichen Ausbildungsmittel kostenlos zur Verfügung zu stellen?', ARRAY['Die zuständige Kammer (IHK/HWK).', 'Die Berufsschule.', 'Der Ausbildende (Betrieb).', 'Der Auszubildende muss diese selbst finanzieren.'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 100),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Pflicht verbietet es dem Auszubildenden, ohne Einwilligung des Ausbildenden Geschäfte im Geschäftszweig des Betriebs für eigene Rechnung zu tätigen?', ARRAY['Schweigepflicht.', 'Fürsorgepflicht.', 'Wettbewerbsverbot.', 'Sorgfaltspflicht.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 101),
  ((select id from public.question_categories where key = 'exam_prep'), 'Mit welcher Frist kann ein Auszubildender kündigen, wenn er die Berufsausbildung aufgeben oder sich für eine andere Berufstätigkeit ausbilden lassen will?', ARRAY['Ohne Einhaltung einer Frist (fristlos).', 'Mit einer Frist von zwei Wochen.', 'Mit einer Frist von vier Wochen.', 'Nur zum Ende des jeweiligen Ausbildungsjahres.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 102),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was passiert rechtlich, wenn ein Auszubildender nach bestandener Abschlussprüfung im Betrieb weiterbeschäftigt wird, ohne dass eine ausdrückliche Vereinbarung getroffen wurde?', ARRAY['Das Ausbildungsverhältnis verlängert sich automatisch um 6 Monate.', 'Ein Arbeitsverhältnis auf unbestimmte Zeit gilt als begründet.', 'Es entsteht ein befristetes Arbeitsverhältnis für ein Jahr.', 'Der Auszubildende arbeitet ohne Rechtsgrundlage und hat keinen Lohnanspruch.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 103),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Reihenfolge gelten die Regelungen im Arbeitsrecht primär, wenn es sich um ''nachgiebiges Recht'' handelt?', ARRAY['EU-Recht → Arbeitsgesetzgebung → Tarifvertrag → Einzelarbeitsvertrag.', 'Einzelarbeitsvertrag → Betriebsvereinbarung → Tarifvertrag → Arbeitsgesetzgebung → EU-Recht.', 'Tarifvertrag → EU-Recht → Einzelarbeitsvertrag.', 'Nur die Arbeitsgesetzgebung des Staates ist maßgebend.'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 104),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was besagt das ''Günstigkeitsprinzip'' bei abweichenden Regelungen im nachgiebigen Recht?', ARRAY['Abweichungen sind nur zulässig, wenn sie für den Arbeitgeber kostengünstiger sind.', 'Abweichungen sind nur zulässig, wenn sie zugunsten des Arbeitnehmers getroffen werden.', 'Es muss immer die Regelung gewählt werden, die für den Staat am günstigsten ist.', 'Abweichungen sind grundsätzlich verboten.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 105),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ab welcher Anzahl von ständigen Arbeitnehmern wird in einem Unternehmen ein Wirtschaftsausschuss gebildet?', ARRAY['Mehr als 5 Arbeitnehmer.', 'Mehr als 20 Arbeitnehmer.', 'Mehr als 50 Arbeitnehmer.', 'Mehr als 100 Arbeitnehmer.'], 3, 'hard', ARRAY['arbeitsrecht']::text[], 106),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchen Angelegenheiten hat der Betriebsrat ein echtes Mitbestimmungsrecht, bei dem Maßnahmen erst mit seiner Zustimmung wirksam werden?', ARRAY['Wirtschaftliche Angelegenheiten.', 'Personelle Angelegenheiten (z. B. Kündigungen).', 'Soziale Angelegenheiten.', 'Nur bei der Information über neue Investitionen.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 107),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie setzt sich die Einigungsstelle zur Beilegung von Meinungsverschiedenheiten zwischen Betriebsrat und Arbeitgeber zusammen?', ARRAY['Aus drei Richtern des zuständigen Arbeitsgerichts.', 'Aus einem unparteiischen Vorsitzenden und Beisitzern (je zur Hälfte von Arbeitgeber und Betriebsrat).', 'Aus dem Wirtschaftsausschuss und der Gewerkschaftsleitung.', 'Nur aus Vertretern der IHK.'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 108),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist das Hauptmerkmal der objektorientierten Programmierung (OOP) laut der Definition im Test?', ARRAY['Die strikte Trennung von Daten und Programmlogik in verschiedenen Dateien.', 'Ein formaler Ansatz, der Daten und zugehörige Aktionen (Methoden) in logischen Strukturen (Objekten) zusammenführt.', 'Die ausschließliche Verwendung von globalen Variablen zur Steuerung großer Anwendungen.', 'Ein Verfahren, bei dem Funktionen keine Parameter übergeben werden dürfen.'], 1, 'easy', ARRAY['softwareentwicklung']::text[], 109),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter dem Prinzip der ''Kapselung'' in der OOP?', ARRAY['Dass aus einer Klasse immer nur genau ein Objekt instanziiert werden darf.', 'Dass der Zugriff auf Attribute einer Klasse primär über deren Methoden erfolgen soll.', 'Das Verpacken des gesamten Quellcodes in eine einzige ausführbare Datei.', 'Die automatische Verschlüsselung von Datenbankinhalten.'], 1, 'medium', ARRAY['it_sicherheit', 'softwareentwicklung']::text[], 110),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Aussage über die Sichtbarkeit von Methoden ist korrekt?', ARRAY['Methoden müssen in jeder Klasse grundsätzlich ''public'' sein.', 'Eine Methode kann auch ''private'' sein.', 'Private Methoden können nur über Interfaces angesprochen werden.', 'Methoden dürfen innerhalb einer Klasse nicht von anderen Methoden aufgerufen werden.'], 1, 'easy', ARRAY['softwareentwicklung']::text[], 111),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wann wird ein Konstruktor innerhalb einer Klasse aufgerufen?', ARRAY['Nur wenn das Programm einen schwerwiegenden Fehler meldet.', 'Manuell durch den Benutzer nach dem Programmstart.', 'Automatisch bei der Instanziierung (Erzeugung) eines Objekts.', 'Sobald eine abstrakte Klasse in ein Interface umgewandelt wird.'], 2, 'easy', ARRAY['softwareentwicklung']::text[], 112),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie verhalten sich ''public''-Attribute innerhalb der Klasse, in der sie definiert wurden?', ARRAY['Sie sind innerhalb der eigenen Klasse nicht sichtbar.', 'Sie verhalten sich innerhalb der Klasse wie private Attribute (Zugriff ist möglich).', 'Sie können nur durch statische Methoden verändert werden.', 'Sie müssen zwingend im Header der Klasse gesperrt werden.'], 1, 'medium', ARRAY['softwareentwicklung']::text[], 113),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie können statische Methoden in einem Programm angesprochen werden?', ARRAY['Ausschließlich über eine zuvor erzeugte Instanz der Klasse.', 'Auch ohne Instanz direkt über den Klassennamen.', 'Nur innerhalb eines Konstruktors.', 'Überhaupt nicht, da sie nur als Platzhalter für spätere Methoden dienen.'], 1, 'medium', ARRAY['softwareentwicklung']::text[], 114),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Aussage zur Vererbung und zu Interfaces trifft zu?', ARRAY['Interfaces werden technisch gesehen nicht wie Klassen vererbt.', 'Die Begriffe ''abstrakte Klasse'' und ''Interface'' haben die identische Bedeutung.', 'Bei der Vererbung werden grundsätzlich nur die Methoden, aber nie die Attribute weitergegeben.', 'Aus einer Klasse kann grundsätzlich immer nur ein einziges Objekt instanziiert werden.'], 0, 'hard', ARRAY['softwareentwicklung']::text[], 115),
  ((select id from public.question_categories where key = 'exam_prep'), 'Warum ist der OOP-Ansatz besonders beim Entwickeln großer Anwendungen wichtig?', ARRAY['Weil er die Ausführungsgeschwindigkeit auf alten Rechnern verdoppelt.', 'Weil er die Fähigkeit verbessert, mit Softwarekomplexität umzugehen.', 'Weil er die Verwendung von Kommentaren im Quellcode überflüssig macht.', 'Weil dadurch keine Datentypen mehr definiert werden müssen.'], 1, 'easy', ARRAY['softwareentwicklung']::text[], 116),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchem Produktionsfaktor werden im Rahmen der Leistungserstellung Materialien wie Kabelkanäle und Kabelbinder zugeordnet?', ARRAY['Werkstoffe', 'Betriebsmittel', 'Ausführende Arbeitskräfte', 'Leitende Arbeitskräfte'], 0, 'easy', ARRAY['wirtschaft']::text[], 117),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welche Kategorie der Produktionsfaktoren fallen langlebige Güter wie PCs, Laptops oder Geschäftsräume?', ARRAY['Werkstoffe', 'Betriebsmittel', 'Ausführende Arbeitskräfte', 'Dispositiver Faktor'], 1, 'easy', ARRAY['wirtschaft']::text[], 118),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird die Geschäftsleitung innerhalb der menschlichen Produktionsfaktoren klassifiziert?', ARRAY['Werkstoffe', 'Ausführende Arbeitskräfte', 'Leitende Arbeitskräfte', 'Hilfsstoffe'], 2, 'easy', ARRAY['wirtschaft']::text[], 119),
  ((select id from public.question_categories where key = 'exam_prep'), 'Mit welcher Formel wird die Wirtschaftlichkeit eines Unternehmensbereichs ermittelt?', ARRAY['Aufwand : Ertrag', 'Ertrag - Aufwand', 'Ertrag : Aufwand', '(Leistung / Zeit) * 100'], 2, 'medium', ARRAY['wirtschaft']::text[], 120),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches primäre Ziel verfolgen öffentlich-rechtliche Betriebe (z. B. kommunale Versorger)?', ARRAY['Den Anteilseignern möglichst hohe Gewinne auszuschütten.', 'Die Bevölkerung soll bestmöglich mit Gütern und Dienstleistungen versorgt werden.', 'Die Einnahmen der Kommune sollen ohne Rücksicht auf Kosten maximiert werden.', 'Die Kosten sollen unabhängig von der Versorgungsqualität auf Null reduziert werden.'], 1, 'easy', ARRAY['wirtschaft']::text[], 121),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Gesetz enthält die wesentlichen Vorschriften zur Durchführung und Regelung der Berufsausbildung in Deutschland?', ARRAY['Jugendarbeitsschutzgesetz', 'Betriebsverfassungsgesetz', 'Bürgerliches Gesetzbuch', 'Berufsbildungsgesetz'], 3, 'easy', ARRAY['arbeitsrecht']::text[], 122),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Lernort ist im dualen System primär für die Vermittlung der theoretischen Inhalte des Rahmenlehrplans zuständig?', ARRAY['Der Ausbildungsbetrieb', 'Die Berufsschule', 'Die Industrie- und Handelskammer (IHK)', 'Die Bundesagentur für Arbeit'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 123),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer regelt die Prüfungsmodalitäten und nimmt die Abschlussprüfung im Ausbildungsverhältnis ab?', ARRAY['Die Berufsschule', 'Das Bundesministerium für Bildung', 'Die Industrie- und Handelskammer (IHK)', 'Der Ausbildungsbetrieb allein'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 124),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Lernort ist dafür verantwortlich, die Eintragung des Ausbildungsverhältnisses bei der zuständigen Stelle zu beantragen?', ARRAY['Der Ausbildungsbetrieb', 'Die Berufsschule', 'Der Auszubildende selbst', 'Das Arbeitsgericht'], 0, 'easy', ARRAY['arbeitsrecht']::text[], 125),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Auszubildender startet mit 18 Jahren und Abitur eine Ausbildung in NRW. Besteht laut Schulgesetz weiterhin Berufsschulpflicht?', ARRAY['Nein, da er bereits volljährig ist.', 'Nein, da das Abitur die Schulpflicht generell beendet.', 'Ja, wer vor Vollendung des 21. Lebensjahres eine Ausbildung beginnt, ist bis zu deren Ende schulpflichtig.', 'Nur, wenn der Ausbildungsbetrieb ihn ausdrücklich dazu verpflichtet.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 126),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Ziel verfolgt das Instrument ''Europass'' der Europäischen Kommission?', ARRAY['Die kostenlose Bereitstellung von Flugtickets für Auszubildende.', 'Fähigkeiten und Qualifikationen in klarer, europaweit vergleichbarer Form darzustellen.', 'Den rechtlichen Schutz gegen Kündigungen im Ausland.', 'Die automatische Anerkennung jedes deutschen Zeugnisses als Hochschulabschluss.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 127),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Aufgabe gehört laut Gesetz zu den Pflichten eines Betriebsrats?', ARRAY['Die Festlegung der Verkaufspreise des Unternehmens.', 'Darüber zu wachen, dass geltende Gesetze, Unfallverhütungsvorschriften und Tarifverträge eingehalten werden.', 'Die alleinige Entscheidung über die Einstellung neuer Geschäftsführer.', 'Die Organisation von Streiks bei Lohnverhandlungen.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 128),
  ((select id from public.question_categories where key = 'exam_prep'), 'Zwischen welchen Parteien können Tarifverträge abgeschlossen werden?', ARRAY['Zwischen Betriebsrat und Arbeitgeber.', 'Zwischen Gewerkschaften und Arbeitgeberverbänden oder einzelnen Arbeitgebern.', 'Nur zwischen dem Arbeitsministerium und den Kirchen.', 'Zwischen allen Mitarbeitern eines Betriebs und dem Staat.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 129),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lange darf die Probezeit in einem Berufsausbildungsverhältnis laut § 20 BBiG höchstens dauern?', ARRAY['1 Monat', '3 Monate', '4 Monate', '6 Monate'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 130),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Art von Tarifvertrag werden die konkreten Entgeltregelungen wie Stundenlöhne, Monatsgehälter und Ausbildungsvergütungen festgelegt?', ARRAY['Manteltarifvertrag', 'Entgelttarifvertrag', 'Rahmen- oder Entgeltrahmentarifvertrag', 'Firmentarifvertrag'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 131),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Regelungen sind typischerweise Bestandteil eines Manteltarifvertrages?', ARRAY['Definition der Entgeltgruppen für Akkordberechnungen', 'Konkrete Höhe der jährlichen Sonderzahlungen', 'Arbeitsbedingungen wie Probezeit, Erholungsurlaub und wöchentliche Arbeitszeit', 'Steuerfreie Inflationsausgleichsprämien'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 132),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man im Tarifrecht unter einer ''Öffnungsklausel''?', ARRAY['Sie erlaubt Arbeitnehmern, bis zu 12 Stunden am Tag ohne Überstundenzuschlag zu arbeiten.', 'Sie erlaubt abweichende Regelungen im Tarifvertrag durch Arbeitsverträge oder Betriebsvereinbarungen in besonderen Situationen.', 'Sie schreibt fest, dass Unternehmen niemals vom Tarifvertrag abweichen dürfen.', 'Sie ist eine gesetzliche Regelung, die Tarifverträge grundsätzlich für ungültig erklärt.'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 133),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Versicherungsträger ist für die gesetzliche Unfallversicherung zuständig?', ARRAY['Bundesagentur für Arbeit', 'Deutsche Rentenversicherung', 'Berufsgenossenschaft', 'Pflegekasse'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 134),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer ist der Träger der Arbeitslosenversicherung in Deutschland?', ARRAY['Bundesagentur für Arbeit', 'Krankenkassen', 'Rentenversicherung Bund', 'Sozialamt der jeweiligen Kommune'], 0, 'easy', ARRAY['arbeitsrecht']::text[], 135),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Sozialversicherung wird ausschließlich durch die Beiträge des Arbeitgebers finanziert?', ARRAY['Krankenversicherung', 'Rentenversicherung', 'Unfallversicherung', 'Pflegeversicherung'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 136),
  ((select id from public.question_categories where key = 'exam_prep'), 'Für welche Sozialversicherung wurde im Jahr 1995 eine gesetzliche Pflicht eingeführt?', ARRAY['Arbeitslosenversicherung', 'Pflegeversicherung', 'Rentenversicherung', 'Krankenversicherung'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 137),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Sozialversicherung zahlen kinderlose Mitglieder über 23 Jahre einen zusätzlichen Beitragszuschlag von 0,60 %?', ARRAY['Krankenversicherung', 'Pflegeversicherung', 'Rentenversicherung', 'Arbeitslosenversicherung'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 138),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Versicherung gewährt primär Leistungen wie ärztliche Behandlungen und Arzneien?', ARRAY['Krankenversicherung', 'Pflegeversicherung', 'Unfallversicherung', 'Rentenversicherung'], 0, 'easy', ARRAY['arbeitsrecht']::text[], 139),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Sozialversicherung weist in der Regel den höchsten Prozentsatz beim Versicherungsbeitrag auf?', ARRAY['Pflegeversicherung', 'Arbeitslosenversicherung', 'Rentenversicherung', 'Unfallversicherung'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 140),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was garantiert die 1961 vom Europarat ins Leben gerufene Europäische Sozialcharta (ESC) der Bevölkerung der Unterzeichnerstaaten?', ARRAY['Einen jährlichen Musikwettbewerb für Komponisten und Texter.', 'Umfassende soziale Rechte, wie z. B. das Recht auf Berufsausbildung, Arbeit und soziale Sicherheit.', 'Die Garantie, dass jedes Land seine individuellen Standards ohne Rücksprache senken darf.', 'Den freien Zugang zu allen europäischen Streaming-Diensten.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 141),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Mitarbeiter im Lager soll künftig weitreichendere Aufgaben übernehmen und macht dafür einen Gabelstaplerführerschein. Um welche Art der Bildungsmaßnahme handelt es sich?', ARRAY['Fortbildung', 'Weiterbildung', 'Umschulung', 'Erstausbildung'], 0, 'medium', ARRAY['arbeitsrecht']::text[], 142),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Buchhalter strebt den Abschluss zum Bilanzbuchhalter bei der IHK an, um künftig die Erstellung von Jahresabschlüssen zu übernehmen. Wie wird diese Maßnahme klassifiziert?', ARRAY['Fortbildung', 'Weiterbildung', 'Ausbildung', 'Trainee-Programm'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 143),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Gemeinsamkeit weisen die Rechtsformen OHG (Offene Handelsgesellschaft) und KG (Kommanditgesellschaft) auf?', ARRAY['Bei beiden ist ein gesetzliches Mindestkapital von 25.000 € vorgeschrieben.', 'Bei beiden sind für die Gründung zwei oder mehr Personen erforderlich.', 'In beiden Gesellschaften haften alle Gesellschafter nur mit ihrer Einlage.', 'Nur die KG gilt rechtlich als Personengesellschaft.'], 1, 'medium', ARRAY['wirtschaft']::text[], 144),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Regelung zur Geschäftsführung gilt typischerweise für die OHG im Gegensatz zur KG?', ARRAY['Nur ein externer Manager darf die Geschäfte führen.', 'Jeder Gesellschafter hat die Pflicht und das Recht zur Geschäftsführung.', 'Die Geschäftsführung wird von der IHK bestimmt.', 'Kommanditisten führen die Geschäfte allein.'], 1, 'medium', ARRAY['wirtschaft']::text[], 145),
  ((select id from public.question_categories where key = 'exam_prep'), 'Für welche Gesellschafter gilt grundsätzlich ein Wettbewerbsverbot?', ARRAY['Nur für die Kommanditisten einer KG.', 'Für alle Gesellschafter einer OHG.', 'Nur für die Aktionäre einer AG.', 'Das Wettbewerbsverbot ist in Personengesellschaften gesetzlich verboten.'], 1, 'hard', ARRAY['arbeitsrecht', 'wirtschaft']::text[], 146),
  ((select id from public.question_categories where key = 'exam_prep'), 'An welches Organ müssen sich Gründer wenden, um die Eintragung eines Unternehmens in das Handelsregister zu veranlassen?', ARRAY['Industrie- und Handelskammer (IHK)', 'Arbeitsgericht', 'Amtsgericht', 'Handwerkskammer'], 2, 'easy', ARRAY['arbeitsrecht', 'wirtschaft']::text[], 147),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Abteilung des Handelsregisters werden Kapitalgesellschaften (wie GmbH oder AG) geführt?', ARRAY['Abteilung A', 'Abteilung B', 'Abteilung C', 'Abteilung D'], 1, 'medium', ARRAY['wirtschaft']::text[], 148),
  ((select id from public.question_categories where key = 'exam_prep'), 'Warum wird eine GmbH im Sinne des Handelsgesetzbuches (HGB) als ''Kaufmann'' eingestuft?', ARRAY['Sie ist aufgrund ihrer gewählten Rechtsform ein sogenannter Formkaufmann.', 'Sie ist nur dann Kaufmann, wenn sie mehr als 10 Mitarbeiter beschäftigt.', 'Jede Kapitalgesellschaft kann frei wählen, ob sie als Kaufmann gelten möchte.', 'Sie gilt als Ist-Kaufmann, sofern ihr Umsatz eine bestimmte Grenze überschreitet.'], 0, 'hard', ARRAY['wirtschaft']::text[], 149),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche formale Anforderung stellt der Gesetzgeber an den Gesellschaftsvertrag einer GmbH?', ARRAY['Eine einfache schriftliche Vereinbarung ist ausreichend.', 'Der Vertrag bedarf zwingend einer notariellen Form.', 'Der Vertrag muss lediglich mündlich vor der IHK bestätigt werden.', 'Es ist gesetzlich gar kein Gesellschaftsvertrag vorgeschrieben.'], 1, 'medium', ARRAY['wirtschaft']::text[], 150),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchen Zusatz muss ein Prokurist bei der Unterzeichnung von Geschäftsdokumenten zwingend verwenden?', ARRAY['i. A. (im Auftrag)', 'i. V. (in Vertretung)', 'ppa. (per procura)', 'Einzelunterschrift ohne Zusatz'], 2, 'medium', ARRAY['wirtschaft']::text[], 151),
  ((select id from public.question_categories where key = 'exam_prep'), 'Inwieweit kann die Prokura im Außenverhältnis gegenüber Dritten beschränkt werden?', ARRAY['Sie kann im Außenverhältnis gar nicht beschränkt werden.', 'Sie kann auf Geschäfte unter 5.000 € begrenzt werden.', 'Sie gilt nur für Einkäufe, nicht für Verkäufe.', 'Sie kann zeitlich auf die Dauer von sechs Monaten befristet werden.'], 0, 'hard', ARRAY['wirtschaft']::text[], 152),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Nachbarunternehmen stellt Kartons unentgeltlich zur Verfügung, wobei am Folgetag gleichartige Kartons zurückgegeben werden müssen. Welcher Vertrag liegt vor?', ARRAY['Leihvertrag', 'Mietvertrag', 'Sachdarlehensvertrag', 'Schenkungsvertrag'], 2, 'hard', ARRAY['wirtschaft']::text[], 153),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ein IT-Systemhaus plant den Zusammenschluss mit einem regionalen Konkurrenten der gleichen Wirtschaftsstufe. Wie wird diese Form des Zusammenschlusses genannt?', ARRAY['Vertikaler Zusammenschluss', 'Horizontaler Zusammenschluss', 'Lateraler Zusammenschluss', 'Diagonaler Zusammenschluss'], 1, 'medium', ARRAY['wirtschaft']::text[], 154),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist eine typische Auswirkung der weltweiten Arbeitsteilung auf Unternehmen und Umwelt?', ARRAY['Die Abhängigkeit von internationalen Zulieferern nimmt ab.', 'Soziale und ökologische Standards werden weltweit garantiert.', 'Es kommt insgesamt zu höheren Umweltbelastungen und Abhängigkeiten von Zulieferern.', 'Das weltweite Transportaufkommen wird drastisch reduziert.'], 2, 'medium', ARRAY['wirtschaft']::text[], 155),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Zusammenschluss liegt vor, wenn rechtlich und wirtschaftlich selbständige Unternehmen kooperieren, um den Wettbewerb (z. B. durch Preisabsprachen) auszuschalten?', ARRAY['Fusion', 'Konzern', 'Kartell', 'Arbeitsgemeinschaft'], 2, 'medium', ARRAY['wirtschaft']::text[], 156),
  ((select id from public.question_categories where key = 'exam_prep'), 'Bei welcher Form des Zusammenschlusses geben Unternehmen ihre rechtliche und wirtschaftliche Selbständigkeit vollständig auf?', ARRAY['Kartell', 'Fusion', 'Konzern', 'Interessengemeinschaft'], 1, 'medium', ARRAY['wirtschaft']::text[], 157),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie nennt man den Zusammenschluss mehrerer rechtlich selbstständiger Unternehmen zu einer wirtschaftlichen Einheit unter einer gemeinsamen Leitung?', ARRAY['Konzern', 'Fusion', 'Kartell', 'Genossenschaft'], 0, 'medium', ARRAY['wirtschaft']::text[], 158),
  ((select id from public.question_categories where key = 'exam_prep'), 'Mit welcher Formel wird die Eigenkapitalrentabilität ermittelt?', ARRAY['Ertrag : Aufwand', 'Ausbringungsmenge : Einsatzmenge', '(Gewinn · 100) : eingesetztes Kapital', '(Umsatzerlöse · 100) : Gewinn'], 2, 'medium', ARRAY['wirtschaft']::text[], 159),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lautet die Formel zur Berechnung der Produktivität?', ARRAY['Ertrag : Aufwand', 'Ausbringungsmenge : Einsatzmenge', '(Gewinn · 100) : eingesetztes Kapital', 'Aufwendungen : Erträge'], 1, 'medium', ARRAY['wirtschaft']::text[], 160),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird der Punkt im Preis-Mengen-Diagramm genannt, an dem sich die Angebots- und die Nachfragekurve schneiden?', ARRAY['Angebotsüberhang', 'Nachfrageüberhang', 'Gleichgewichtspreis', 'Mindestpreis'], 2, 'easy', ARRAY['wirtschaft']::text[], 161),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was passiert am Markt, wenn der aktuelle Preis über dem Gleichgewichtspreis liegt?', ARRAY['Es entsteht ein Nachfrageüberhang.', 'Es entsteht ein Angebotsüberhang.', 'Die Nachfrage steigt ins Unendliche.', 'Der Markt ist im perfekten Gleichgewicht.'], 1, 'medium', ARRAY['wirtschaft']::text[], 162),
