  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Voraussetzung muss erfüllt sein, damit ein Auszubildender zur Abschlussprüfung zugelassen wird?', ARRAY['Das Führen der vorgeschriebenen schriftlichen Ausbildungsnachweise (Berichtsheft).', 'Ein Notendurchschnitt von mindestens 3,0 im Berufsschulzeugnis.', 'Weniger als 50 Fehlstunden in der Berufsschule.', 'Vorlage eines guten Arbeitszeugnisses bei der IHK.'], 0, 'medium', ARRAY['arbeitsrecht']::text[], 170),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wann endet das Ausbildungsverhältnis genau, wenn der Auszubildende die Prüfung erfolgreich besteht?', ARRAY['Mit dem im Vertrag festgelegten Datum (z. B. 31. Juli).', 'Am Tag der schriftlichen Prüfung.', 'Am Tag der erfolgreichen (mündlichen) Abschlussprüfung.', 'Erst mit der Aushändigung des Berufsschulzeugnisses.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 171),
