  ((select id from public.question_categories where key = 'exam_prep'), 'Ein Arbeitgeber spricht am 15. März eine ordentliche Kündigung aus. Der Mitarbeiter ist 30 Jahre alt und seit 5 Jahren im Betrieb. Zu welchem Termin wird die Kündigung laut BGB wirksam?', ARRAY['Zum 15. April (vier Wochen Frist).', 'Zum 31. Mai (zwei Monate zum Ende eines Kalendermonats).', 'Zum 15. Juni (drei Monate Frist).', 'Sofort am Tag der Aussprache.'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 179),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lange ist die gesetzliche Kündigungsfrist für einen Arbeitgeber, wenn das Arbeitsverhältnis im Betrieb seit 20 Jahren besteht?', ARRAY['Vier Monate zum Ende eines Kalendermonats.', 'Fünf Monate zum Ende eines Kalendermonats.', 'Sieben Monate zum Ende eines Kalendermonats.', 'Ein Jahr zum Ende des Quartals.'], 2, 'hard', ARRAY['arbeitsrecht']::text[], 180),
