  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Unterzeichnungszusatz ist für einen Mitarbeiter mit allgemeiner Handlungsvollmacht vorgeschrieben?', ARRAY['ppa.', 'i. A.', 'i. V.', 'Einzelunterschrift ohne Zusatz'], 2, 'easy', ARRAY['wirtschaft']::text[], 191),
