  ((select id from public.question_categories where key = 'exam_prep'), 'Welches UML-Diagramm stellt den zeitlichen Ablauf von Nachrichten zwischen Objekten dar?', ARRAY['Klassendiagramm', 'Aktivitätsdiagramm', 'Sequenzdiagramm', 'ER-Diagramm'], 2, 'easy', ARRAY['softwareentwicklung']::text[], 270),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was besagt die sogenannte "10er-Regel" im Qualitätsmanagement bezüglich der Fehlerkosten?', ARRAY['Die Fehlerkosten verringern sich um den Faktor 10, wenn der Fehler erst beim Kunden entdeckt wird.', 'Die Fehlerkosten steigen um den Faktor 10 je Produktionsstufe in der Wertschöpfungskette, in der ein Fehler unentdeckt bleibt.', 'Ein Produkt darf maximal 10 Fehler aufweisen, um noch als ''gut'' zu gelten.', 'Nach 10 Jahren muss jedes Qualitätsmanagementsystem komplett neu zertifiziert werden.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 271),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welche Kategorien lassen sich Qualitätskosten traditionell unterteilen?', ARRAY['Personalkosten, Materialkosten und Mietkosten.', 'Fehlerverhütungskosten, Prüfkosten und Fehlerkosten.', 'Fixkosten, variable Kosten und kalkulatorische Kosten.', 'Anschaffungskosten, Betriebskosten und Entsorgungskosten.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 272),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter "Opportunitätskosten" im Kontext von Qualitätsmängeln?', ARRAY['Die Kosten für die Entsorgung von fehlerhaften Produkten (Ausschuss).', 'Entgangene Gewinne, die durch Imageverlust aufgrund von Qualitätsmängeln entstehen.', 'Die Kosten für die Durchführung eines externen Audits.', 'Die Einsparungen, die durch den Verzicht auf Endkontrollen erzielt werden.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 273),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Anforderungen werden im Kano-Modell vom Kunden als selbstverständlich vorausgesetzt und führen bei Erfüllung nicht zu erhöhter Zufriedenheit?', ARRAY['Leistungsanforderungen', 'Begeisterungsanforderungen', 'Basisanforderungen', 'Überraschungsanforderungen'], 2, 'easy', ARRAY['qualitaetsmanagement']::text[], 274),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Eigenschaft kennzeichnet "Begeisterungsanforderungen" im Kano-Modell?', ARRAY['Sie werden vom Kunden im Lastenheft ausdrücklich gefordert.', 'Ihr Fehlen führt nicht zu Unzufriedenheit, da der Kunde sie nicht erwartet, aber ihre Erfüllung steigert die Zufriedenheit überproportional.', 'Sie müssen zwingend in der Bedienungsanleitung stehen.', 'Sie wandeln sich mit der Zeit niemals in Basisanforderungen um.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 275),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wofür steht die Abkürzung PDCA im Zusammenhang mit dem Deming-Kreis zur kontinuierlichen Verbesserung?', ARRAY['Product, Design, Control, Analysis', 'Plan, Do, Check, Act', 'Process, Documentation, Certification, Audit', 'Performance, Development, Communication, Assessment'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 276),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Norm der ISO-9000-Reihe beschreibt die Grundlagen und Begriffe für Qualitätsmanagementsysteme?', ARRAY['DIN EN ISO 9001', 'DIN EN ISO 9004', 'DIN EN ISO 9000', 'DIN EN ISO 19011'], 2, 'medium', ARRAY['qualitaetsmanagement']::text[], 277),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie wird ein Audit bezeichnet, das von einer unabhängigen, externen Organisation (z. B. TÜV oder DEKRA) durchgeführt wird?', ARRAY['First Party Audit', 'Second Party Audit', 'Third Party Audit', 'Internal Self-Assessment'], 2, 'easy', ARRAY['qualitaetsmanagement']::text[], 278),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches der "Sieben Qualitätswerkzeuge" (Q7) dient primär der Analyse von Ursache-Wirkungs-Zusammenhängen (auch Fischgräten-Diagramm genannt)?', ARRAY['Pareto-Diagramm', 'Histogramm', 'Ishikawa-Diagramm', 'Qualitätsregelkarte'], 2, 'easy', ARRAY['qualitaetsmanagement']::text[], 279),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie berechnet sich die Risikoprioritätszahl (RPZ) im Rahmen einer FMEA (Fehlermöglichkeits- und Einflussanalyse)?', ARRAY['Auftretenswahrscheinlichkeit (A) + Bedeutung (B) + Entdeckungswahrscheinlichkeit (E)', '(A + B) × E', 'Auftretenswahrscheinlichkeit (A) × Bedeutung (B) × Entdeckungswahrscheinlichkeit (E)', 'Bedeutung (B) / (A × E)'], 2, 'hard', ARRAY['qualitaetsmanagement']::text[], 280),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Ziel verfolgt die FMEA (Failure Mode and Effects Analysis)?', ARRAY['Die nachträgliche Korrektur von Fehlern, wenn das Produkt bereits beim Kunden ist.', 'Vorsorgende Fehlervermeidung anstelle einer nachsorgenden Fehlererkennung.', 'Die Berechnung der maximalen Produktionsgeschwindigkeit.', 'Die Dokumentation der Mitarbeiter-Fehlzeiten.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 281),
  ((select id from public.question_categories where key = 'exam_prep'), 'Warum ist die wahrgenommene Qualitätsunsicherheit beim Kunden beim Kauf von Dienstleistungen (immateriellen Gütern) oft größer als bei Sachgütern?', ARRAY['Weil Dienstleistungen vor dem Vertragsabschluss nicht besichtigt oder getestet werden können.', 'Weil Dienstleistungen immer billiger sind als Sachgüter.', 'Weil Dienstleister keine Zertifikate besitzen dürfen.', 'Weil Ergebnisse von Dienstleistungen immer objektiv bewertbar sind.'], 0, 'medium', ARRAY['qualitaetsmanagement']::text[], 282),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Ziel verfolgt der QM-Grundsatz "Engagement von Personen"?', ARRAY['Dass alle Mitarbeiter ausschließlich Anweisungen der Geschäftsführung befolgen.', 'Dass kompetente und befugte Mitarbeiter auf allen Ebenen in die Wertschöpfung einbezogen werden.', 'Dass die Anzahl der Mitarbeiter pro Abteilung jährlich um 10 % steigt.', 'Dass Mitarbeiter nur für die Fehlerhaftung zuständig sind.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 283),
  ((select id from public.question_categories where key = 'exam_prep'), 'Warum ist "Führung" (Leadership) ein zentraler Grundsatz im Qualitätsmanagement?', ARRAY['Weil Führungskräfte die alleinige Verantwortung für alle produzierten Fehler tragen.', 'Weil sie durch ihre Vorbildfunktion sicherstellen, dass die Qualitätsphilosophie im ganzen Unternehmen verstanden und gelebt wird.', 'Damit die Hierarchien im Unternehmen möglichst starr bleiben.', 'Um die Kosten für externe Auditoren einzusparen.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 284),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist der Kern des "prozessorientierten Ansatzes" im QM?', ARRAY['Dass jede Abteilung als isolierte Einheit arbeitet, um Fehlerquellen schneller zu finden.', 'Dass Tätigkeiten als verknüpfte Prozesse verstanden und gesteuert werden, um konsistente Ergebnisse zu erzielen.', 'Dass alle Prozesse ausschließlich manuell und ohne IT-Unterstützung dokumentiert werden müssen.', 'Die Reduzierung der Produktion auf einen einzigen, einfachen Arbeitsschritt.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 285),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Nutzen ergibt sich aus dem Grundsatz der "faktengestützten Entscheidungsfindung"?', ARRAY['Entscheidungen werden schneller getroffen, da man nicht auf Datenanalysen warten muss.', 'Eine höhere Objektivität und Vertrauen in die Wirksamkeit von Maßnahmen durch die Analyse von Kennzahlen und Daten.', 'Die Abschaffung aller Besprechungen, da Daten für sich selbst sprechen.', 'Dass nur die Meinung des erfahrensten Mitarbeiters zählt.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 286),
  ((select id from public.question_categories where key = 'exam_prep'), 'In den Unterlagen wird der "8D-Report" erwähnt. Wofür wird dieses Instrument primär eingesetzt?', ARRAY['Zur Erstellung eines neuen Produktdesigns.', 'Zur systematischen Bearbeitung von Reklamationen und zur nachhaltigen Fehlerabstellung in acht Schritten.', 'Zur Berechnung der jährlichen Dividende.', 'Um die Mitarbeiterzufriedenheit in der Kantine zu messen.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 287),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches der "Sieben Qualitätswerkzeuge" (Q7) nutzt man, um eine Datensammlung nach Häufigkeiten zu sortieren und die "wichtigen Wenigen" von den "unwichtigen Vielen" zu trennen?', ARRAY['Ishikawa-Diagramm', 'Pareto-Diagramm', 'Korrelationsdiagramm', 'Flussdiagramm'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 288),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter dem Begriff "Total Quality Management" (TQM) laut deiner QM-Übersicht?', ARRAY['Eine Methode, die sich ausschließlich auf die Endkontrolle der Produkte konzentriert.', 'Eine umfassende Managementphilosophie, die die Qualität in den Mittelpunkt stellt und alle Mitarbeiter sowie Kunden einbezieht.', 'Ein Computerprogramm zur automatischen Fehlerkorrektur im Quellcode.', 'Die vollständige Auslagerung der Qualitätssicherung an externe Dienstleister.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 289),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was kennzeichnet ein "Integriertes Managementsystem" (IMS)?', ARRAY['Dass für jeden Bereich (Qualität, Umwelt, Sicherheit) eine völlig eigene, getrennte Dokumentation existiert.', 'Die Kombination verschiedener Managementsysteme (z. B. ISO 9001, ISO 14001, ISO 27001), um Synergien zu nutzen und Kosten zu sparen.', 'Dass das Unternehmen keine externen Audits mehr durchführen lassen muss.', 'Die ausschließliche Nutzung von Cloud-Systemen für die Datenspeicherung.'], 1, 'medium', ARRAY['qualitaetsmanagement']::text[], 290),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Zeitraum ist für die Gültigkeit einer Zertifizierung in Deutschland (z. B. durch TÜV oder DEKRA) üblich?', ARRAY['1 Jahr', '3 Jahre', '5 Jahre', 'Unbegrenzt, solange kein Fehler auftritt.'], 1, 'easy', ARRAY['qualitaetsmanagement']::text[], 291),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchen Artikeln des Grundgesetzes (GG) ist der Sozialstaatsgedanke in Deutschland ausdrücklich verankert?', ARRAY['Art. 1 und Art. 5', 'Art. 20 und Art. 28', 'Art. 12 und Art. 14', 'Art. 38 und Art. 40'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 292),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter der "Beitragsbemessungsgrenze" in der Sozialversicherung?', ARRAY['Den Mindestbetrag, den ein Arbeitnehmer verdienen muss, um versicherungspflichtig zu sein.', 'Die Grenze, ab der ein Arbeitnehmer von der Versicherungspflicht befreit ist.', 'Der Betrag vom Bruttoentgelt, von dem die Beiträge zur Sozialversicherung höchstens erhoben werden.', 'Die maximale Höhe der Leistungen, die ein Versicherter pro Jahr erhalten kann.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 293),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchen Zweigen der Sozialversicherung hängen die Leistungen nicht von der Höhe der eingezahlten Beiträge ab (Solidaritätsprinzip)?', ARRAY['Renten- und Arbeitslosenversicherung', 'Kranken- und Pflegeversicherung', 'Nur in der Unfallversicherung', 'In allen fünf Zweigen der Sozialversicherung'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 294),
  ((select id from public.question_categories where key = 'exam_prep'), 'Ab welcher Woche der Arbeitsunfähigkeit zahlt die gesetzliche Krankenversicherung in der Regel Krankengeld?', ARRAY['Ab dem ersten Tag der Erkrankung', 'Ab der dritten Woche', 'Ab der siebten Woche', 'Erst nach Ablauf von drei Monaten'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 295),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer ist der Träger der gesetzlichen Rentenversicherung?', ARRAY['Die gesetzlichen Krankenkassen', 'Die Bundesagentur für Arbeit', 'Die Deutsche Rentenversicherung Bund und Regionalträger', 'Die Berufsgenossenschaften'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 296),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer trägt die Beiträge zur gesetzlichen Unfallversicherung?', ARRAY['Arbeitnehmer und Arbeitgeber je zur Hälfte', 'Allein der Arbeitnehmer', 'Allein der Arbeitgeber', 'Der Staat aus allgemeinen Steuermitteln'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 297),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchen Prozentsatz vom pauschalierten Nettoentgelt erhalten Arbeitslose mit Kindern als Arbeitslosengeld I?', ARRAY['60 %', '67 %', '70 %', '80 %'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 298),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer ist laut SGB VII für die Versicherung von Schülern während der Schulzeit und Studenten während der Ausbildung an Hochschulen zuständig?', ARRAY['Die gesetzliche Krankenversicherung', 'Die gesetzliche Unfallversicherung', 'Die soziale Pflegeversicherung', 'Die private Haftpflichtversicherung der Eltern'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 299),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welcher Träger ist für die soziale Pflegeversicherung (SGB XI) verantwortlich?', ARRAY['Die Deutsche Rentenversicherung', 'Die Pflegekassen, die den Krankenkassen angegliedert sind', 'Die Versorgungsämter der Länder', 'Die Bundesagentur für Arbeit'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 300),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Sozialversicherung zahlen kinderlose Arbeitnehmer über 23 Jahren einen zusätzlichen Beitragszuschlag (Stand 2021: 0,25 %)?', ARRAY['Krankenversicherung', 'Rentenversicherung', 'Pflegeversicherung', 'Arbeitslosenversicherung'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 301),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Form des Ausscheidens aus einem Unternehmen basiert auf einer einvernehmlichen Auflösung des Arbeitsverhältnisses ohne Kündigung?', ARRAY['Ordentliche Kündigung', 'Aufhebungsvertrag', 'Änderungskündigung', 'Fristlose Entlassung'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 302),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche allgemeine gesetzliche Kündigungsfrist gilt für einen Arbeitnehmer laut BGB, wenn keine anderen Vereinbarungen getroffen wurden?', ARRAY['Zwei Wochen zum Monatsende', 'Vier Wochen zum 15. oder zum Ende eines Kalendermonats', 'Drei Monate zum Quartalsende', 'Sechs Wochen zum Monatsende'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 303),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was versteht man unter einer "Änderungskündigung"?', ARRAY['Eine Kündigung, die sofort in einen Aufhebungsvertrag umgewandelt wird.', 'Eine fristlose Kündigung aufgrund von Fehlverhalten.', 'Die fristgerechte Kündigung verbunden mit dem Angebot, das Arbeitsverhältnis zu geänderten Bedingungen fortzusetzen.', 'Eine Kündigung, die nur mündlich ausgesprochen werden darf.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 304),
  ((select id from public.question_categories where key = 'exam_prep'), 'Unter welchen Voraussetzungen greift der "allgemeine Kündigungsschutz" nach dem Kündigungsschutzgesetz (KSchG)?', ARRAY['Ab dem ersten Tag der Beschäftigung in jedem Betrieb.', 'Wenn das Arbeitsverhältnis länger als 6 Monate besteht und der Betrieb mehr als 10 Mitarbeiter hat.', 'Nur für Auszubildende nach der Probezeit.', 'Sobald ein schriftlicher Arbeitsvertrag unterzeichnet wurde.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 305),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche drei Gründe können eine ordentliche Kündigung durch den Arbeitgeber im Rahmen des KSchG rechtfertigen?', ARRAY['Politische, religiöse und private Gründe.', 'Personenbedingte, verhaltensbedingte und betriebsbedingte Gründe.', 'Nur die Insolvenz des Unternehmens.', 'Erreichen des Rentenalters, Krankheit und Heirat.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 306),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Kriterien müssen bei einer betriebsbedingten Kündigung im Rahmen der "sozialen Auswahl" berücksichtigt werden?', ARRAY['Nur das Gehalt und die Nationalität.', 'Dauer der Betriebszugehörigkeit, Lebensalter, Unterhaltspflichten und Schwerbehinderung.', 'Sympathie, Wohnortnähe und Sprachkenntnisse.', 'Die Anzahl der Überstunden und die Religionszugehörigkeit.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 307),
  ((select id from public.question_categories where key = 'exam_prep'), 'Innerhalb welcher Frist muss ein Arbeitnehmer Klage beim Arbeitsgericht erheben, wenn er eine Kündigung für sozial ungerechtfertigt hält?', ARRAY['Binnen einer Woche nach Zugang der Kündigung.', 'Binnen zwei Wochen nach Beendigung des Arbeitsverhältnisses.', 'Binnen drei Wochen nach Zugang der schriftlichen Kündigung.', 'Innerhalb von drei Monaten zum Quartalsende.'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 308),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Gesetz schützt Beschäftigte vor Benachteiligungen wegen der ethnischen Herkunft, des Geschlechts, der Religion oder des Alters?', ARRAY['Betriebsverfassungsgesetz (BetrVG)', 'Allgemeines Gleichbehandlungsgesetz (AGG)', 'Bundesurlaubsgesetz (BUrlG)', 'Mutterschutzgesetz (MuSchG)'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 309),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie lange dürfen werdende Mütter vor der Entbindung und nach der Geburt laut Mutterschutzgesetz (MuSchG) grundsätzlich nicht beschäftigt werden?', ARRAY['4 Wochen vorher / 6 Wochen nachher', '6 Wochen vorher / 8 Wochen nachher', '8 Wochen vorher / 12 Wochen nachher', '12 Wochen vorher / 12 Wochen nachher'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 310),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welchen Nachteil hat ein Arbeitnehmer bei Abschluss eines Aufhebungsvertrages bezüglich des Arbeitslosengeldes?', ARRAY['Er erhält lebenslang kein Arbeitslosengeld mehr.', 'Das Arbeitslosengeld wird um 50 % gekürzt.', 'Er erhält erst nach Ablauf einer zwölfwöchigen Sperrzeit Arbeitslosengeld.', 'Er muss das Arbeitslosengeld im Voraus selbst bezahlen.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 311),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wann ist eine außerordentliche (fristlose) Kündigung zulässig?', ARRAY['Wenn der Arbeitnehmer einen besseren Job gefunden hat.', 'Wenn ein wichtiger Grund vorliegt, der die Fortsetzung des Verhältnisses unzumutbar macht.', 'Wenn der Arbeitgeber die Betriebskosten senken möchte.', 'Nur während der ersten drei Tage der Probezeit.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 312),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wann müssen die wesentlichen Inhalte des Berufsausbildungsvertrages spätestens schriftlich niedergelegt werden?', ARRAY['Erst nach Ablauf der Probezeit.', 'Spätestens bis zur ersten Zwischenprüfung.', 'Vor Beginn der Ausbildung.', 'Innerhalb der ersten drei Monate nach Ausbildungsbeginn.'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 313),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wer ist laut BBiG dafür verantwortlich, dem Auszubildenden kostenlos die Ausbildungsmittel (z. B. Werkzeuge) zur Verfügung zu stellen?', ARRAY['Die Industrie- und Handelskammer (IHK).', 'Der Ausbildende (Betrieb).', 'Die Berufsschule.', 'Der Auszubildende selbst.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 314),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Pflicht verbietet es dem Auszubildenden, ohne Einwilligung des Betriebes im Geschäftszweig des Ausbildenden für eigene Rechnung tätig zu werden?', ARRAY['Schweigepflicht.', 'Sorgfaltspflicht.', 'Wettbewerbsverbot.', 'Gehorsamspflicht.'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 315),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchem zeitlichen Rahmen muss die Probezeit laut Berufsbildungsgesetz (§ 20) liegen?', ARRAY['Mindestens 1 Monat, höchstens 3 Monate.', 'Mindestens 1 Monat, höchstens 4 Monate.', 'Mindestens 3 Monate, höchstens 6 Monate.', 'Es gibt keine gesetzliche Untergrenze.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 316),
  ((select id from public.question_categories where key = 'exam_prep'), 'Innerhalb welcher Frist muss eine außerordentliche (fristlose) Kündigung erfolgen, nachdem der Kündigungsgrund bekannt wurde?', ARRAY['Innerhalb von drei Werktagen.', 'Innerhalb einer Woche.', 'Innerhalb von zwei Wochen.', 'Innerhalb eines Monats.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 317),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welche Frist muss ein Auszubildender einhalten, wenn er die Ausbildung aufgeben oder sich für eine andere Berufstätigkeit ausbilden lassen möchte?', ARRAY['Keine Frist (fristlos).', 'Zwei Wochen.', 'Vier Wochen.', 'Drei Monate zum Quartalsende.'], 2, 'easy', ARRAY['arbeitsrecht']::text[], 318),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welcher Reihenfolge werden Regelungen im Arbeitsrecht angewendet, wenn es sich um "nachgiebiges Recht" handelt?', ARRAY['Gesetz → Tarifvertrag → Einzelarbeitsvertrag.', 'Einzelarbeitsvertrag → Betriebsvereinbarung → Tarifvertrag → Gesetz.', 'EU-Recht → Gesetz → Tarifvertrag → Einzelvertrag.', 'Tarifvertrag steht immer an erster Stelle.'], 1, 'hard', ARRAY['arbeitsrecht']::text[], 319),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was besagt das "Günstigkeitsprinzip" im Arbeitsrecht?', ARRAY['Der Arbeitgeber darf immer die für ihn günstigste Regelung wählen.', 'Tarifverträge sind grundsätzlich günstiger als Gesetze.', 'Abweichungen vom Gesetz sind zulässig, wenn sie für den Arbeitnehmer vorteilhafter sind.', 'Verträge müssen so kurz wie möglich gehalten werden.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 320),
  ((select id from public.question_categories where key = 'exam_prep'), 'Unter welcher Voraussetzung wird in einem Unternehmen eine Jugend- und Auszubildendenvertretung (JAV) gewählt?', ARRAY['In jedem Ausbildungsbetrieb, unabhängig von der Größe.', 'Wenn mindestens 20 Auszubildende beschäftigt sind.', 'Wenn mindestens 5 Arbeitnehmer unter 18 Jahren oder Azubis unter 25 Jahren vorhanden sind.', 'Nur wenn der Arbeitgeber dies ausdrücklich wünscht.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 321),
  ((select id from public.question_categories where key = 'exam_prep'), 'In welchen Angelegenheiten hat der Betriebsrat ein echtes Mitbestimmungsrecht (Maßnahmen werden erst mit Zustimmung wirksam)?', ARRAY['Wirtschaftliche Angelegenheiten.', 'Personelle Angelegenheiten (z. B. Widerspruch bei Kündigung).', 'Soziale Angelegenheiten (z. B. Pausenzeiten, Urlaubsgrundsätze).', 'Investitionsentscheidungen.'], 2, 'medium', ARRAY['arbeitsrecht']::text[], 322),
  ((select id from public.question_categories where key = 'exam_prep'), 'Wie setzt sich die Einigungsstelle zur Beilegung von Differenzen zwischen Arbeitgeber und Betriebsrat zusammen?', ARRAY['Nur aus Vertretern der Gewerkschaften.', 'Aus einem unparteiischen Vorsitzenden und Beisitzern von AG und BR (je zur Hälfte).', 'Aus einem Richter des Arbeitsgerichts allein.', 'Aus der kompletten Belegschaft des Betriebes.'], 1, 'medium', ARRAY['arbeitsrecht']::text[], 323),
  ((select id from public.question_categories where key = 'exam_prep'), 'Welches Merkmal kennzeichnet den autoritären Führungsstil?', ARRAY['Der Vorgesetzte legt Probleme vor und bittet um Lösungsvorschläge.', 'Der Vorgesetzte trifft Entscheidungen allein und gibt sie als Anweisung weiter.', 'Die Mitarbeiter können innerhalb gesetzter Grenzen völlig frei handeln.', 'Entscheidungen werden grundsätzlich in der Gruppe demokratisch getroffen.'], 1, 'easy', ARRAY['arbeitsrecht']::text[], 324),
  ((select id from public.question_categories where key = 'exam_prep'), 'Was ist das Ziel der Führungstechnik "Management by Objectives"?', ARRAY['Führung durch Zielvereinbarungen.', 'Führung nach dem Ausnahmeprinzip (nur Eingriff bei Abweichungen).', 'Führung durch Delegation aller Aufgaben.', 'Führung durch ständige Kontrolle jedes Arbeitsschrittes.'], 0, 'easy', ARRAY['arbeitsrecht']::text[], 325);
